programs.haiku:
"""Copula detector. The component fires on forms of the verb "be" (is, are, was,
were, be, been, being, am) and on the contracted 's, 're, 'm after a pronoun, and on
an adverb or "not" placed right after a "be" form, before its predicate starts. It is
strongest after a modal or "to" (can be, must be, to be), weaker after "there" and
"here" as subject, and silent on everything else."""

from collections.abc import Mapping

import wordnet

READS = ()

BE = {"is", "are", "was", "were", "be", "been", "being", "am"}
CONTRACTED_BE = {"'s", "’s", "'re", "’re", "'m", "’m"}
PRONOUN = {"it", "he", "she", "i", "you", "we", "they", "that", "what", "who"}
EXISTENTIAL = {"there", "here"}
MODAL_OR_TO = {"can", "may", "must", "would", "will", "should", "could", "might", "shall", "to"}


def _word(s):
    return s.strip().lower()


def _is_adverb(w):
    pos = wordnet.parts_of_speech(w)
    return ("adverb" in pos and "adjective" not in pos) or w == "not"


def step(carry, prefix, upstream: Mapping):
    cur = _word(prefix.token_strings[-1])
    same_doc = len(prefix.document_ids) > 1 and prefix.document_ids[-2] == prefix.document_ids[-1]
    prev = _word(prefix.token_strings[-2]) if same_doc else ""
    if cur in BE:
        if prev in EXISTENTIAL:
            value = 0.7
        elif prev in MODAL_OR_TO:
            value = 3.4
        else:
            value = 2.5
    elif cur in CONTRACTED_BE:
        if prev in EXISTENTIAL:
            value = 0.7
        elif prev in PRONOUN:
            value = 1.6
        else:
            value = 0.0
    elif prev in BE and _is_adverb(cur):
        value = 1.1
    else:
        value = 0.0
    return carry, float(value)

"""Layer 15 MLP down-projection component 2216: fires where a text starts a new point.

What it does, in plain terms: when a text is laying out a series of points, this
component is positive at the marks that open each new point, and near zero or slightly
negative elsewhere. Its output promotes words like "also", "another" and "还有", which
continue a list.

Strongest, in order:
- the point after a list number at the start of a line ("3." or "2)"), about 2.5;
- an additive connective that opens a point ("Secondly", "Moreover", "Также", "另外"),
  about 1, and the comma right after it ("Secondly,", "Кроме того,"), about 2;
- a bullet or heading mark at the start of a line ("•", "-", "*", "##"), about 1;
- a number at the start of a line, about 0.7; the word "also", about 0.5.
Mild negatives: "however" and conjunctions like "and", "or", "but", "of".
Everything else gets a small constant near the average (-0.05).

This captures the spikes only. Most of the variance is a diffuse background that no
simple rule here predicts, so the explained variance is small.
"""

READS = ()

BASE = -0.05
NEG = {"and": -0.15, "or": -0.2, "but": -0.15, "of": -0.15, "however": -0.45}
TRANSITIONS = {
    "secondly", "firstly", "finally", "lastly", "moreover", "furthermore",
    "additionally", "besides", "также", "кроме", "además", "另外", "此外",
    "而且", "其次", "还有", "ещё", "еще",
}
MARKERS = {"•", "##", "###", "#", "-", "*"}
PUNCT_AFTER_NUMBER = {".", ")", ":", "．", "、"}


def step(carry, prefix, upstream):
    """Activation at the newest token, from the token text alone (no carried state)."""
    toks = prefix.token_strings
    t = toks[-1].strip().lower()
    prev = toks[-2].strip().lower() if len(toks) > 1 else ""
    line_start = len(toks) == 1 or "\n" in toks[-2]
    numbered = len(toks) > 2 and prev.isdigit() and ("\n" in toks[-3] or len(toks) == 3)
    if t in PUNCT_AFTER_NUMBER and numbered:
        return carry, 2.5
    if t.isdigit() and line_start:
        return carry, 0.7
    if t in MARKERS and line_start:
        return carry, 1.0
    if t in TRANSITIONS:
        return carry, 1.0
    if t == "also":
        return carry, 0.5
    if t in {",", "，"} and prev in TRANSITIONS:
        return carry, 2.0
    return carry, NEG.get(t, BASE)

"""Layer 15 MLP unit 2226 (down_proj component 2226): "a new thing is being introduced".

What it does: this component reads mostly MLP hidden unit 2226 of layer 15 (about three
quarters of its input direction's norm). It is a weak, broad feature. Its clearest use is on the words that open a noun phrase
for a new object:
  - "by" (mean about 1.6), e.g. "increased by", "amended by";
  - "a" / "an", and counting words ("two", "three", "some", "new", ...), most
    strongly right after a verb of creating or introducing ("create a", "define a",
    "there is a", "have a"), and somewhat after any other verb;
  - "into", and the creating verbs themselves ("create", "introduce", "define").
It is pushed to zero or slightly negative when the same word follows a preposition
of means or context ("using a", "with a", "from a", "through a", "between a").

The program scores each position from the word itself and its neighbours: the word
just before it and any creating or using word in the last few tokens of its document.
It predicts a few tenths to about 1.6, and 0 for everything else. It explains about
4% of the variance (r about 0.2). A token-lookup table reaches about 6% and a
previous-word lookup about 10%, so the rule gives up some accuracy for legibility.
"""
import wordnet

READS = ()

INDEFINITE = {"a", "an"}
COUNTS = {"one", "two", "three", "four", "five", "six", "some", "several", "each", "any",
          "certain", "another", "separate", "new"}
CREATING_VERBS = {"create", "introduce", "define", "develop", "exists"}
CREATING_CUES = CREATING_VERBS | {"exist", "add", "suppose", "make", "write", "build", "given", "there"}
USING_WORDS = {"using", "use", "used", "with", "from", "through", "for", "between", "allows", "provide"}
WINDOW = 5


def is_verb(word):
    return word.isalpha() and "verb" in wordnet.parts_of_speech(word)


def step(carry, prefix, upstream):
    word = prefix.token_strings[-1].strip().lower()
    n = len(prefix.token_strings)
    doc = prefix.document_ids[-1]
    prev = ""
    if n > 1 and prefix.document_ids[-2] == doc:
        prev = prefix.token_strings[-2].strip().lower()

    if word == "by":
        return carry, 1.6
    if word in CREATING_VERBS:
        return carry, 1.3
    if word == "into":
        return carry, 0.7
    if word not in INDEFINITE and word not in COUNTS:
        return carry, 0.0

    # An article or counting word: how strongly it opens a new object.
    if prev in CREATING_CUES:
        value = 0.9
    elif prev in USING_WORDS:
        value = 0.0
    elif is_verb(prev):
        value = 0.7 if word in INDEFINITE else 0.6
    else:
        value = 0.2 if word in INDEFINITE else 0.35
    recent = [prefix.token_strings[i].strip().lower() for i in range(max(0, n - 1 - WINDOW), n - 1)
              if prefix.document_ids[i] == doc]
    if any(x in CREATING_CUES for x in recent):
        value += 0.8
    if any(x in USING_WORDS for x in recent):
        value -= 0.1
    return carry, value

"""Layer 15, MLP hidden unit 2228 (the component `layers.15.mlp.down_proj:2228`).

The component is almost exactly one hidden unit of layer 15's MLP: 63% of its input direction
sits on that unit, and its output direction promotes "combine / combination / blend / together"
(and 结合, "combined with"). So it fires where the model is about to write a *combining* phrase:
the article after a verb of using or requiring ("using a [combination of]", "requires a",
"involves a", "through a", "via a", "by a"), the word "blending", and the connector right after
a mixing word ("mix of", "blend of", "balance between").

This program is a plain rule table over the last word or two. It is a description of where the
unit is high, not a model of how it is computed, and it explains only a little of the variance:
most of the unit's activation is small, diffuse and context-dependent, and everywhere else the
program predicts a small negative baseline, the unit's usual value.
"""

READS = ()

BASELINE = -0.04
ARTICLES = {"a", "an"}
# word before an article -> activation on the article (mean over the training rows)
SETUP_WORDS = {"involves": 2.4, "requires": 1.3, "used": 1.0, "uses": 0.9, "using": 0.8,
               "use": 0.7, "through": 0.6, "via": 0.6, "by": 0.4}
MIXING_WORDS = {"mix", "blend", "balance", "interaction", "combination", "combine", "combined", "mixture"}
CONNECTORS = {"of", "between", "and", "with"}


def word(text):
    return text.strip().lower()


def step(carry, prefix, upstream):
    cur = word(prefix.token_strings[-1])
    same_doc = len(prefix.document_ids) > 1 and prefix.document_ids[-2] == prefix.document_ids[-1]
    prev = word(prefix.token_strings[-2]) if same_doc else ""
    if cur == "blending":
        value = 2.0
    elif cur in ARTICLES and prev in SETUP_WORDS:
        value = SETUP_WORDS[prev]
    elif cur in CONNECTORS and prev in MIXING_WORDS:
        value = 1.0
    else:
        value = BASELINE
    return carry, value
